/bin/zsh -c "docker exec -i invoice-schema-check psql -U postgres -v ON_ERROR_STOP=1 <<'SQL'
INSERT INTO accounts VALUES ('demo', true), ('real', false);
INSERT INTO orders(id,account_id) VALUES ('d','demo'), ('r','real');
SET ROLE app;
SELECT complete_order('d'), complete_order('r');
DO "'$$ BEGIN
  BEGIN DELETE FROM invoice_audit; RAISE EXCEPTION '"'delete succeeded'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
  PERFORM set_config('app.purge', 'true', false);
  BEGIN DELETE FROM invoice_audit; RAISE EXCEPTION 'delete succeeded'; EXCEPTION WHEN insufficient_privilege THEN NULL; END;
END "'$$;
SELECT purge_demo_account('"'real');
RESET ROLE;
CREATE TABLE extra_reference (id text REFERENCES orders(id) ON DELETE RESTRICT);
SET ROLE app;
DO "'$$ BEGIN
  BEGIN PERFORM purge_demo_account('"'demo'); RAISE EXCEPTION 'preflight failed'; EXCEPTION WHEN raise_exception THEN IF SQLERRM NOT LIKE 'unhandled foreign key%' THEN RAISE; END IF; END;
END "'$$;
RESET ROLE;
DROP TABLE extra_reference;
SET ROLE app;
SELECT purge_demo_account('"'demo');
DO "'$$ BEGIN
  IF EXISTS (SELECT FROM accounts WHERE id='"'demo') OR EXISTS (SELECT FROM invoice_audit WHERE order_id='d') OR NOT EXISTS (SELECT FROM invoice_audit WHERE order_id='r') THEN RAISE EXCEPTION 'incorrect purge'; END IF;
END "'$$;
RESET ROLE;
SQL'

